-- PREWORK: public-schema adaptation + independently synthetic rows.

-- One-time creation intentionally fails if this isolated database already exists.

CREATE DATABASE HACKATHON_D2K_PREWORK COMMENT='Pre-event baseline. Public WWI schema subset; synthetic rows. No proprietary assets.';

CREATE SCHEMA HACKATHON_D2K_PREWORK.RAW;

USE SCHEMA HACKATHON_D2K_PREWORK.RAW;

USE WAREHOUSE DEFAULT_WH;

CREATE TABLE CUSTOMERS (CUSTOMERID NUMBER NOT NULL, CUSTOMERNAME VARCHAR NOT NULL, BILLTOCUSTOMERID NUMBER NOT NULL) COMMENT='Simplified WWI-compatible sample schema; independently generated synthetic rows, seed 231026';


CREATE TABLE STOCKITEMS (STOCKITEMID NUMBER NOT NULL, STOCKITEMNAME VARCHAR NOT NULL, UNITPRICE NUMBER(18,2) NOT NULL, TAXRATE NUMBER(18,3) NOT NULL) COMMENT='Simplified WWI-compatible sample schema; independently generated synthetic rows, seed 231026';


CREATE TABLE STOCKGROUPS (STOCKGROUPID NUMBER NOT NULL, STOCKGROUPNAME VARCHAR NOT NULL) COMMENT='Simplified WWI-compatible sample schema; independently generated synthetic rows, seed 231026';


CREATE TABLE STOCKITEMSTOCKGROUPS (STOCKITEMSTOCKGROUPID NUMBER NOT NULL, STOCKITEMID NUMBER NOT NULL, STOCKGROUPID NUMBER NOT NULL) COMMENT='Simplified WWI-compatible sample schema; independently generated synthetic rows, seed 231026';


CREATE TABLE ORDERS (ORDERID NUMBER NOT NULL, CUSTOMERID NUMBER NOT NULL, ORDERDATE DATE NOT NULL, EXPECTEDDELIVERYDATE DATE NOT NULL) COMMENT='Simplified WWI-compatible sample schema; independently generated synthetic rows, seed 231026';


CREATE TABLE ORDERLINES (ORDERLINEID NUMBER NOT NULL, ORDERID NUMBER NOT NULL, STOCKITEMID NUMBER NOT NULL, QUANTITY NUMBER NOT NULL, UNITPRICE NUMBER(18,2) NOT NULL, TAXRATE NUMBER(18,3) NOT NULL, PICKEDQUANTITY NUMBER NOT NULL) COMMENT='Simplified WWI-compatible sample schema; independently generated synthetic rows, seed 231026';


CREATE TABLE INVOICES (INVOICEID NUMBER NOT NULL, CUSTOMERID NUMBER NOT NULL, BILLTOCUSTOMERID NUMBER NOT NULL, ORDERID NUMBER NOT NULL, INVOICEDATE DATE NOT NULL) COMMENT='Simplified WWI-compatible sample schema; independently generated synthetic rows, seed 231026';


CREATE TABLE INVOICELINES (INVOICELINEID NUMBER NOT NULL, INVOICEID NUMBER NOT NULL, STOCKITEMID NUMBER NOT NULL, QUANTITY NUMBER NOT NULL, UNITPRICE NUMBER(18,2) NOT NULL, TAXRATE NUMBER(18,3) NOT NULL, TAXAMOUNT NUMBER(18,2) NOT NULL, EXTENDEDPRICE NUMBER(18,2) NOT NULL) COMMENT='Simplified WWI-compatible sample schema; independently generated synthetic rows, seed 231026';


SELECT 'CUSTOMERS' AS TABLE_NAME, COUNT(*) AS ROW_COUNT FROM CUSTOMERS UNION ALL SELECT 'STOCKITEMS',COUNT(*) FROM STOCKITEMS UNION ALL SELECT 'STOCKGROUPS',COUNT(*) FROM STOCKGROUPS UNION ALL SELECT 'STOCKITEMSTOCKGROUPS',COUNT(*) FROM STOCKITEMSTOCKGROUPS UNION ALL SELECT 'ORDERS',COUNT(*) FROM ORDERS UNION ALL SELECT 'ORDERLINES',COUNT(*) FROM ORDERLINES UNION ALL SELECT 'INVOICES',COUNT(*) FROM INVOICES UNION ALL SELECT 'INVOICELINES',COUNT(*) FROM INVOICELINES;